extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var basket := await instantiate_main_scene() as Sprite2D
	if not check("basket_exists", basket != null, "La scena principale Basket si istanzia correttamente"):
		return

	var initial_lives = get_prop(basket, "lives", 3)
	var expected_initial = get_prop(basket, "INITIAL_LIVES", 3)
	check(
		"initial_lives",
		initial_lives == expected_initial,
		"Le vite iniziali devono corrispondere a INITIAL_LIVES (sono %d, attese %d)" % [initial_lives, expected_initial]
	)

	# Primo colpo
	call_if_exists(basket, "take_damage", [1])
	await wait_frames(2)

	var lives_after_first = get_prop(basket, "lives", 0)
	var lives_reduced_ok := (lives_after_first == initial_lives - 1)
	check(
		"lives_reduced",
		lives_reduced_ok,
		"Dopo il primo danno le vite scendono di 1 (da %d a %d)" % [initial_lives, lives_after_first]
	)

	var is_inv = get_prop(basket, "is_invulnerable", false)
	check("is_invulnerable_true", is_inv == true, "Dopo aver subito danno il cesto deve essere invulnerabile")
	check("modulate_semi_transparent", basket.modulate.a < 0.9, "Il cesto diventa semitrasparente (modulate.a ridotto, è %.2f)" % basket.modulate.a)

	# Secondo colpo dopo mezzo secondo: deve essere ignorato
	await wait_seconds(0.5)
	call_if_exists(basket, "take_damage", [1])
	await wait_frames(2)
	var lives_during_inv = get_prop(basket, "lives", 0)
	check(
		"damage_ignored",
		lives_during_inv == lives_after_first,
		"Un colpo subito durante l'invulnerabilità non deve togliere vite (vite: %d)" % lives_during_inv
	)

	# Aspetta la fine del secondo di invulnerabilità
	await wait_seconds(0.6)
	var is_inv_after = get_prop(basket, "is_invulnerable", true)
	check("invulnerability_ended", is_inv_after == false, "Trascorsa l'attesa di 1 secondo l'invulnerabilità termina")
	check("modulate_restored", absf(basket.modulate.a - 1.0) < 0.05, "L'opacità modulate.a torna a 1.0 (è %.2f)" % basket.modulate.a)
